/deep/ .ivu-checkbox-wrapper{
	font-size 12px;
    margin-right 30px
}
/deep/ .ivu-checkbox{
    margin-right 6px
}
/deep/ .ivu-checkbox-inner{
    width 14px;
    height: 14px
    font-size: 12px
}
/deep/ .ivu-checkbox-checked .ivu-checkbox-inner:after{
    top: 1px;
    left: 4px;
}
/deep/.ivu-card{
    border-radius: 0;
	font-size inherit;

}
.warpper{
    max-width: 1200px;
}
.fixed-card {
    position: fixed;
    right: 0;
    bottom: 0;
    left: 200px;
    z-index: 45;
    box-shadow: 0 -1px 2px rgb(240, 240, 240);

    /deep/ .ivu-card-body {
        padding: 15px 16px 14px;
        text-align: center;
    }

    .ivu-form-item {
        margin-bottom: 0;
    }

    /deep/ .ivu-form-item-content {
        margin-right: 124px;
        text-align: center;
    }

    .ivu-btn {
        height: 36px;
        padding: 0 20px;
    }
}
    .link{
        background: #F6F7F9;
        border-radius: 2px;
        padding 20px
    }
    .change{
        color: #2D8CF0;
        cursor pointer
    }
// 隐藏滚动条
.ticket-content::-webkit-scrollbar {
    display: none;
}
.ticket-preview {
    display flex
    flex-direction: column
    align-items: center
}
.out-line{
    width: 271px;
    height: 7px;
    background: #EEEEEE;
    border-radius: 4px;
}
// 动画高度从0变为100%
@keyframes show {
    0% {
        margin-top: -70vh;
    }
    100% {
        margin-top: 0;
    }
}
.ticket-preview{
    overflow hidden;
    height: 70vh;
}
.ticket-content{
    position relative
    top: -3px;
    animation show 2s ease-in-out forwards;
    width: 260px;
    max-height: 70vh;
    overflow-y: scroll
    overflow-x: hidden
    background-color: #fff;
    padding: 20px 15px 15px 15px;
    box-shadow: 0px 4px 10px 0px rgba(0,0,0,0.1);
    border-radius: 1px 1px 1px 1px;
    font-size: 12px;
    font-weight: 400;
    color #333;
    line-height: 18px;
    .form-box{
        display: flex;
        .label{
            white-space: nowrap
        }
    }
    .ticket-header{
        font-weight: 500;
        font-size: 18px;
        text-align: center;
        margin-bottom: 20px;
    }
    // 下划线虚线
    .btn-line{
        border-bottom: 1px dashed #eee;
        padding 10px 0
    }
    .star-line{
      font-family: "Microsoft YaHei";
      font-size: 12px;
      display: flex;
      justify-content: center;
      overflow: hidden;
      white-space: nowrap;
    }
    .fw-500{
        font-weight: 500;
    }
    .code{
        display flex
        flex-direction: column
        align-items: center

        text-align center
        #qrcode{
            margin: 25px 0 0px
        }
    }


}
 .bottom-notice{
    width: 260px;
    margin-left 1px
    height 13px
    position: relative;
}
.image {
    width: 100%;
    height 100%
    position absolute
    top -6px;
}
